import React, { useEffect, useState } from "react";
import api from "../api/api";
import { useAuth } from "../context/AuthContext";

export default function OwnerDashboard() {
  const { user, logout } = useAuth();
  const [stores, setStores] = useState([]);
  const [ratingsForStore, setRatingsForStore] = useState(null);

  const [oldPass, setOldPass] = useState("");
  const [newPass, setNewPass] = useState("");
  const [passMsg, setPassMsg] = useState("");

  const loadStores = async () => {
    try {
      const res = await api.get("/stores");
      // filter to only my stores
      const owned = res.data.stores.filter(s => s.owner && s.owner.id === user.id);
      // Note: Backend getStores might return owner object. If not, filtered by checking s.owner.id if eager loaded or separate query.
      // Based on controller, it includes owner.
      setStores(owned);
    } catch (err) {
      console.error(err);
    }
  };

  useEffect(() => { loadStores(); }, []);

  const openRatings = async (store) => {
    try {
      const res = await api.get(`/ratings/store/${store.id}`);
      setRatingsForStore({ store, data: res.data });
    } catch (err) {
      console.error(err);
    }
  };

  const handlePassUpdate = async (e) => {
    e.preventDefault();
    try {
      await api.put(`/users/${user.id}/password`, {
        oldPassword: oldPass,
        newPassword: newPass
      });
      setPassMsg("Password updated successfully!");
      setOldPass("");
      setNewPass("");
    } catch (err) {
      setPassMsg("Error updating password: " + (err.response?.data?.message || err.message));
    }
  };

  return (
    <div className="p-6 bg-gray-50 min-h-screen">
      <div className="flex justify-between items-center mb-8">
        <h2 className="text-3xl font-bold text-gray-800">Owner Dashboard</h2>
        <button onClick={logout} className="bg-red-500 hover:bg-red-600 text-white px-4 py-2 rounded shadow">
          Logout
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Update Password */}
        <div className="bg-white p-6 rounded-lg shadow h-fit">
          <h3 className="text-xl font-semibold mb-4 border-b pb-2">Update Password</h3>
          <form onSubmit={handlePassUpdate} className="space-y-3">
            <input
              type="password"
              placeholder="Old Password"
              className="w-full p-2 border rounded"
              value={oldPass}
              onChange={(e) => setOldPass(e.target.value)}
              required
            />
            <input
              type="password"
              placeholder="New Password"
              className="w-full p-2 border rounded"
              value={newPass}
              onChange={(e) => setNewPass(e.target.value)}
              required
            />
            <button type="submit" className="w-full bg-blue-600 text-white py-2 rounded hover:bg-blue-700 transition">Update</button>
          </form>
          {passMsg && <p className="mt-2 text-sm text-blue-600">{passMsg}</p>}
        </div>

        {/* Stores List */}
        <div className="lg:col-span-2 space-y-8">
          <div className="bg-white p-6 rounded-lg shadow">
            <h3 className="text-xl font-semibold mb-4 border-b pb-2">Your Stores</h3>
            {stores.length === 0 ? (
              <p className="text-gray-500">You don't have any stores assigned yet.</p>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {stores.map(s => (
                  <div key={s.id} className="border p-4 rounded-lg hover:shadow-md transition bg-gray-50">
                    <h4 className="font-bold text-lg">{s.name}</h4>
                    <p className="text-sm text-gray-600 mb-2">{s.address}</p>
                    <div className="flex justify-between items-center">
                      <span className="font-bold text-yellow-600">{s.averageRating} ★ <span className="text-xs text-gray-400 font-normal">({s.totalRatings})</span></span>
                      <button
                        onClick={() => openRatings(s)}
                        className="text-sm bg-indigo-100 text-indigo-700 px-3 py-1 rounded hover:bg-indigo-200"
                      >
                        View Ratings
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Ratings View */}
          {ratingsForStore && (
            <div className="bg-white p-6 rounded-lg shadow animate-fade-in">
              <div className="flex justify-between items-center mb-4 border-b pb-2">
                <h3 className="text-xl font-semibold">
                  Ratings for <span className="text-blue-600">{ratingsForStore.store.name}</span>
                </h3>
                <span className="text-lg font-bold text-yellow-600">{ratingsForStore.data.averageRating} ★ Avg</span>
              </div>

              {ratingsForStore.data.ratings.length === 0 ? (
                <p className="text-gray-500">No ratings yet.</p>
              ) : (
                <div className="space-y-3 max-h-96 overflow-y-auto">
                  {ratingsForStore.data.ratings.map(r => (
                    <div key={r.id} className="border-b pb-2 last:border-0">
                      <div className="flex justify-between">
                        <span className="font-bold text-gray-800">{r.user?.name || "Unknown User"}</span>
                        <span className="font-bold text-yellow-600">{r.value} ★</span>
                      </div>
                      {r.comment && <p className="text-gray-600 text-sm mt-1">"{r.comment}"</p>}
                      <p className="text-xs text-gray-400 mt-1">{new Date(r.createdAt).toLocaleDateString()}</p>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
